function transform(event, out, ctx) {
  const field = event.value !== undefined ? 'value' : 'mass_flow';
  event[field] = event[field] * 1.8 + 32.0;
  out.collect(event);
}

function transform(event, out, ctx) {
  const field = event.value !== undefined ? 'value' : 'mass_flow';
  let value = event[field];
  for (let i = 0; i < 1000; i++) {
    value = Math.sin(value) + Math.sqrt(Math.abs(value) + 1.0);
  }
  event[field] = value;
  out.collect(event);
}

